"use strict";const t={1:"新手旅人",2:"逐光者",3:"窥秘人",4:"守夜人",5:"追索者",6:"秘术学徒",7:"命运之眼",8:"序列守望者",9:"星象师",10:"诡秘侍者",11:"牧羊人",12:"断罪者",13:"窃梦者",14:"命运之蛇",15:"旅团长",16:"时之虫",17:"奇迹师",18:"诡秘之主",19:"命运编织者",20:"旧日支配者"};exports.levelBadge=function(n){if(null==n||""===n)return"";const e=Math.trunc(Number(n));return!Number.isFinite(e)||e<0?"":"Lv."+e+" "+function(n){const e=Math.trunc(Number(n));return!Number.isFinite(e)||e<1?"未启程者":e>20?"不可名状者":t[e]||"旅人"}(e)};
